window.QUIZ = (window.QUIZ || []).concat([
  {"id":"10-001","ch":10,"sec":"10.1","page":185,"type":"recall","level":1,"q":"About what share of the world's irrigation, and of U.S. irrigation, uses surface methods?","opts":["About 45% worldwide and 84% in the U.S.","About 50% worldwide and 10% to 15% in the U.S.","About 84% worldwide and 35% to 45% in the U.S.","About 95% worldwide and 60% to 70% in the U.S."],"a":2,"why":"The book cites FAO (2021) and USDA (2019): roughly 84% of world irrigation and 35% to 45% of U.S. irrigation is surface irrigation.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-002","ch":10,"sec":"10.1","page":185,"type":"recall","level":1,"q":"Which three methods make up surface irrigation?","opts":["Border, flood sprinkler and microspray","Furrow, drip and center pivot","Border, furrow and basin","Basin, subirrigation and sprinkler"],"a":2,"why":"Surface irrigation includes border, furrow and basin irrigation (Figure 10.1), all of which let water flow over the soil surface by gravity.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-003","ch":10,"sec":"10.1","page":186,"type":"recall","level":1,"q":"What land slopes are usually acceptable for surface irrigation?","opts":["Between 3% and 6%","Less than 0.01%","Less than 2%","Less than 5%"],"a":2,"why":"Slopes that are too steep cause excess runoff and erosion, and acceptable slopes are usually less than 2%. Slope uniformity matters too, so water does not collect in depressions.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-004","ch":10,"sec":"10.1","page":186,"type":"concept","level":2,"q":"Why is a soil with a very high infiltration rate a problem for surface irrigation?","opts":["Much more water infiltrates near the inlet than at the downstream end, which is the last point to get water","The soil seals and stops all infiltration after the first hour","Water advances too quickly and erodes the furrows","Runoff from the end of the field becomes excessive"],"a":0,"why":"With high intake, water soaks in near the inlet while it slowly advances, so the inlet gets far more than the far end. Fast advance and high runoff are the opposite problem, from low intake soils.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-005","ch":10,"sec":"10.1","page":186,"type":"concept","level":2,"q":"What usually happens when a surface irrigated field is too long or the inflow is too small?","opts":["Runoff becomes the main loss at the downstream end","Surface storage increases and recession becomes faster","Advance takes a long time, giving nonuniform distribution and excessive deep percolation","Water reaches the end too quickly and erodes the tail ditch"],"a":2,"why":"A long advance gives the inlet far more opportunity time than the end, so the inlet over-irrigates (deep percolation) while the end gets too little (Figure 10.5).","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-006","ch":10,"sec":"10.1","page":186,"type":"recall","level":2,"q":"How much of the applied water may need to run off a furrow field to get relatively uniform distribution, and what is E_LQ if it is not recovered?","opts":["40% to 50% runoff, with E_LQ usually less than 30%","20% to 30% runoff, with E_LQ usually less than 60% to 70%","No runoff is needed, and E_LQ is usually about 90%","5% to 10% runoff, with E_LQ usually above 85%"],"a":1,"why":"The book says uniform furrow distribution may require 20% to 30% runoff. Without a recovery or reuse system, E_LQ is then usually under 60% to 70%.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-007","ch":10,"sec":"10.1","page":185,"type":"concept","level":1,"q":"In the U.S. Midwest, where most surface irrigation water is pumped from groundwater, what is the main energy cost of surface irrigation?","opts":["Running the tractor for furrow forming","Pumping tailwater back to the field","Lifting the water to the soil surface","Pressurizing the gated pipe to 30 psi"],"a":2,"why":"Surface irrigation needs little pressure, so the main energy cost is the lift from the aquifer to the surface.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-008","ch":10,"sec":"10.1","page":187,"type":"figure","level":1,"q":"In Figure 10.5, where is the zone labeled \"ET less in this zone\" and why?","opts":["At the downstream end, where the field was not fully irrigated","In the middle of the field, where surface storage was greatest","At the inlet end, where deep percolation was greatest","Along the gated pipe, where evaporation was highest"],"a":0,"why":"The wetted zone gets shallower down the field, so the downstream part is not fully irrigated and the crop there uses less water (ET). The inlet end shows deep percolation instead.","eq":null,"calc":null,"fig":"10.5","table":null},
  {"id":"10-009","ch":10,"sec":"10.1","page":186,"type":"scenario","level":2,"q":"A grower asks, \"Can I furrow irrigate this 3% slope with sandy soil instead of buying a pivot?\" What do you tell him?","opts":["It will work if he uses longer furrows","It will work if he waters every furrow instead of every other one","It is ideal, because sandy soil and steep slope both speed the advance","It is a poor fit, since slopes over about 2% cause runoff and erosion and sandy soil puts too much water in at the inlet"],"a":3,"why":"Acceptable surface irrigation slopes are usually under 2%, and high infiltration soils over-irrigate the inlet end. Longer furrows would make the sandy soil problem worse.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-010","ch":10,"sec":"10.2","page":187,"type":"recall","level":1,"q":"In surface irrigation, what are a set and a set time?","opts":["A set is one furrow, and set time is the advance time to its end","A set is the portion of the field watered at one time, and set time is the fixed period water is applied to it","A set is the area of one basin, and set time is the recession time","A set is one irrigation season, and set time is the days between irrigations"],"a":1,"why":"Water is applied to portions of the field (a border strip, a basin, or a group of furrows) called sets, for a fixed period called set time, also called cutoff time.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-011","ch":10,"sec":"10.2","page":189,"type":"recall","level":1,"q":"How is opportunity time at a point in the field defined?","opts":["Recession time minus advance time at that point","Set time minus advance time to the end of the field","Advance time to the end divided by set time","Advance time minus recession time at that point"],"a":0,"why":"Opportunity time is how long water is present to infiltrate: from when the front arrives (advance) to when the surface drains (recession). Advance time to the end divided by set time is the cutoff ratio.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-012","ch":10,"sec":"10.2","page":188,"type":"calc","level":1,"q":"Water takes 2.5 hours to reach the midpoint of a furrow. Using the book's rule of thumb, about how long will it take to reach the downstream end?","opts":["3.3 hours","7.5 hours","10 hours","5.0 hours"],"a":1,"why":"It typically takes about one-third as much time to get halfway as to get all the way, so 2.5 × 3 = 7.5 hours. 5.0 hours assumes the advance is linear, which it is not.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-013","ch":10,"sec":"10.2","page":187,"type":"concept","level":2,"q":"How does surface irrigation differ from sprinkler and microirrigation in what controls where water infiltrates?","opts":["Once water leaves the inlet the soil's infiltration controls the distribution, while in pressurized systems the hardware does","Both are controlled mainly by pump pressure","Both are controlled mainly by crop canopy interception","In surface irrigation the hardware controls distribution, while in pressurized systems the soil does"],"a":0,"why":"Sprinkler and micro hardware can apply water below the soil's intake capacity at each point. In surface irrigation the manager loses control after the inlet and the soil takes over.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-014","ch":10,"sec":"10.2","page":189,"type":"concept","level":2,"q":"For perfectly uniform infiltration on a soil with uniform infiltration characteristics, what must be true of the advance and recession curves?","opts":["The recession curve must be steeper than the advance curve","Advance must reach the end in less than 1 hour","They must be parallel, so opportunity time is equal everywhere","Recession must start at the downstream end"],"a":2,"why":"Equal opportunity time at every point needs advance time to equal recession time along the field, which means parallel curves. The tradeoff, as the book notes later, is excessive runoff.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-015","ch":10,"sec":"10.2","page":189,"type":"concept","level":3,"q":"If recession is slower than advance along a field, how does opportunity time change from inlet to downstream end?","opts":["It stays constant along the field","It increases with distance from the inlet","It becomes zero at the downstream end","It decreases with distance from the inlet"],"a":1,"why":"The book notes that when recession is slower than advance, opportunity time increases with distance. The more common picture, with fast recession, gives decreasing opportunity time.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-016","ch":10,"sec":"10.2","page":188,"type":"figure","level":2,"q":"What does Figure 10.6 show about infiltration on soil cultivated annually?","opts":["Infiltration is the same for all irrigations and all furrows","Subsequent irrigations infiltrate more than the first, and wheel traffic furrows infiltrate more","The first irrigation and wheel traffic furrows both infiltrate less","Subsequent irrigations infiltrate less than the first irrigation, and wheel traffic furrows infiltrate less than non-wheel furrows"],"a":3,"why":"Both panels show the dashed curve (subsequent irrigations, wheel traffic furrows) below the solid curve (first irrigation, non-wheel furrows) at every opportunity time.","eq":null,"calc":null,"fig":"10.6","table":null},
  {"id":"10-017","ch":10,"sec":"10.2","page":188,"type":"figure","level":1,"q":"In Figure 10.7, how long did water take to advance to the end of the 1,200 ft field?","opts":["13 hours","9 hours","4 hours","12 hours"],"a":1,"why":"The advance curve reaches 1,200 ft at 9 hours. 12 hours is the cutoff time, 13 hours is when recession finished at the end, and 4 hours is the opportunity time there.","eq":null,"calc":null,"fig":"10.7","table":null},
  {"id":"10-018","ch":10,"sec":"10.2","page":188,"type":"figure","level":2,"q":"Using Figure 10.7, how long was water present to infiltrate at the downstream end of the field?","opts":["About 12 hours","About 1 hour","About 9 hours","About 4 hours"],"a":3,"why":"Water arrived at 9 hours and the surface drained at about 13 hours, so opportunity time was 13 − 9 = 4 hours. At the inlet it was 12 hours, which is why infiltration is not uniform.","eq":null,"calc":null,"fig":"10.7","table":null},
  {"id":"10-019","ch":10,"sec":"10.2","page":189,"type":"figure","level":2,"q":"At 600 ft from the inlet, advance time was 2.7 hours and recession was at 12.5 hours. Using Figure 10.10, about how much water infiltrated there?","opts":["About 4.2 in","About 2.9 in","About 3.6 in","About 2.0 in"],"a":2,"why":"Opportunity time = 12.5 − 2.7 = 9.8 hours, and Figure 10.10 gives about 3.6 in near 10 hours. Reading 2.7 hours or 12.5 hours directly on the curve gives the wrong values.","eq":null,"calc":null,"fig":"10.10","table":null},
  {"id":"10-020","ch":10,"sec":"10.2","page":189,"type":"table","level":3,"q":"Using Table 10.1, how much less water infiltrated at the downstream end (1,200 ft) than at the inlet, as a percent of the inlet depth?","opts":["About 57% less","About 25% less","About 67% less","About 43% less"],"a":3,"why":"Inlet 4.2 in, end 2.4 in. (4.2 − 2.4) ÷ 4.2 = 0.43, so 43% less. 57% is the ratio 2.4 ÷ 4.2, which is what remains, not the reduction.","eq":null,"calc":null,"fig":null,"table":"10.1"},
  {"id":"10-021","ch":10,"sec":"10.2","page":188,"type":"scenario","level":2,"q":"A grower says, \"On the first irrigation the water barely reached the end in 12 hours, but now it races through on the same number of furrows.\" What explains this and what should he do?","opts":["The soil has become sandier, so he should shorten the furrows permanently","His pump has gained capacity, so he should reduce engine speed","The furrows are eroding, so he should stop irrigating until they are reshaped","Infiltration drops after the first irrigation, so he should re-check advance and adjust stream size or set time each irrigation"],"a":3,"why":"Figure 10.6 shows subsequent irrigations infiltrate less than the first on cultivated soil, so the same stream advances faster. The book's reactive approach adjusts set time and stream size to measured advance.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-022","ch":10,"sec":"10.2","page":188,"type":"scenario","level":2,"q":"A grower notices water in the wheel track furrows reaches the end of the field hours before the other furrows. What is the likely reason?","opts":["Gated pipe outlets on those furrows are always larger","Tractor tires compacted those furrows, lowering their infiltration rate","Wheel track furrows have more crop residue","The wheel track furrows have a steeper slope"],"a":1,"why":"Wheel traffic compacts the soil, and Figure 10.6 shows wheel traffic furrows infiltrate less, so more water moves down the furrow and advance is faster.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-023","ch":10,"sec":"10.3","page":190,"type":"recall","level":1,"q":"What does the surface irrigation volume balance (Eq. 10.1) state?","opts":["Gross application volume = infiltration volume + deep percolation","Infiltration volume = gross application + surface storage + runoff","Runoff volume = gross application + infiltration + surface storage","Gross application volume = infiltration volume + surface storage volume + runoff volume"],"a":3,"why":"Vg = Vz + Vs + Vr, assuming evaporation during application is negligible. Deep percolation is part of the infiltrated volume, not a separate term in Eq. 10.1.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-024","ch":10,"sec":"10.3","page":190,"type":"concept","level":1,"q":"Why can surface storage (V_s or d_s) be set to zero when computing runoff after an irrigation is finished?","opts":["Surface storage is transient, and once recession is complete it has either infiltrated or run off","Surface storage is included in the gross application already","Surface storage is always smaller than evaporation","Surface storage only exists on basins, not furrows"],"a":0,"why":"Water is stored on the surface only while it is flowing. After cutoff and recession, it has infiltrated or left as runoff, so d_s = 0 and Eq. 10.2 gives d_r = d_g − d_z.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-025","ch":10,"sec":"10.3","page":191,"type":"recall","level":2,"q":"For an open-ended system, where along the field does the average infiltration depth (d_z) typically occur?","opts":["At the midpoint of the field","About 25% of the field length from the inlet","At the downstream end","About 60% of the field length from the inlet"],"a":3,"why":"The book says d_z occurs at about 60% of the length from the inlet. In the 1,200 ft example that is 720 ft, where infiltration is 3.5 in.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-026","ch":10,"sec":"10.3","page":190,"type":"concept","level":2,"q":"When a closed runoff recovery system is used, what is the total inflow rate Q_t in Eq. 10.4?","opts":["The original supply flow minus the runoff rate","The original supply flow plus the flow pumped from the recovery system","The original supply flow only","The recovery pump flow only"],"a":1,"why":"Q_t = Q_w + Q_p, the original supply plus water reused on the same field. Using only Q_w underestimates the gross depth applied.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-027","ch":10,"sec":"10.3","page":190,"type":"recall","level":1,"q":"In Eq. 10.3 and 10.4, what value of W do you use when every other furrow is irrigated on 30 in rows?","opts":["30 in","15 in","2.5 ft","60 in"],"a":3,"why":"W is the spacing of watered furrows. Watering every other furrow doubles it to twice the row spacing, 60 in. Using 30 in doubles the computed depth.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-028","ch":10,"sec":"10.3","page":191,"type":"recall","level":1,"q":"What is cutback irrigation?","opts":["Cutting the set time in half every irrigation","Blocking the downstream end of the furrows","Stopping water before it reaches the end of the field","Reducing the furrow stream size after water has advanced across the field"],"a":3,"why":"Cutback uses a large stream during advance, then reduces it once advance is complete, ideally to about the steady infiltration rate of the wetted area. It improves efficiency but needs labor or automation.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-029","ch":10,"sec":"10.3","page":190,"type":"calc","level":2,"q":"Every other furrow is watered on 30 in rows. Each watered furrow gets 15 gpm for 12 hours and is 1,200 ft long. What is the gross application depth?","opts":["2.9 in","3.5 in","5.8 in","1.4 in"],"a":0,"why":"W = 2 × 30 = 60 in. d_g = 1155 × 15 × 12 ÷ (60 × 1,200) = 2.89, about 2.9 in. 5.8 in uses W = 30 in and doubles the depth.","eq":"10.3","calc":"eq-10.3","fig":null,"table":null},
  {"id":"10-030","ch":10,"sec":"10.3","page":190,"type":"calc","level":2,"q":"A field receives 900 gpm on 40 watered furrows, every other furrow on 30 in rows, 1,200 ft long, with a 12 hour set. What is the gross application depth?","opts":["2.2 in","5.2 in","4.3 in","8.7 in"],"a":2,"why":"W = 60 in. d_g = 1155 × 900 × 12 ÷ (40 × 60 × 1,200) = 4.33 in. 8.7 in uses W = 30 in, a common slip when every other furrow is watered.","eq":"10.4","calc":"eq-10.4","fig":null,"table":null},
  {"id":"10-031","ch":10,"sec":"10.3","page":191,"type":"calc","level":2,"q":"A border strip 50 ft wide and 1,320 ft long receives 1,200 gpm for 2.5 hours. What is the gross application depth?","opts":["52.5 in","0.36 in","8.8 in","4.4 in"],"a":3,"why":"d_g = 96.3 × Q_t × t_co ÷ (W_b × L_b) = 96.3 × 1,200 × 2.5 ÷ (50 × 1,320) = 4.38, about 4.4 in. 52.5 in uses the furrow constant 1155, which is for W in inches.","eq":"10.5","calc":"eq-10.5","fig":null,"table":null},
  {"id":"10-032","ch":10,"sec":"10.3","page":191,"type":"calc","level":2,"q":"A level basin 250 ft by 250 ft is filled with 2,000 gpm for 1 hour. What is the gross application depth?","opts":["6.2 in","37 in","0.26 in","3.1 in"],"a":3,"why":"d_g = 96.3 × 2,000 × 1 ÷ (250 × 250) = 3.08, about 3.1 in. 37 in uses 1155 instead of 96.3, and 0.26 in leaves the result in feet.","eq":"10.5","calc":"eq-10.5","fig":null,"table":null},
  {"id":"10-033","ch":10,"sec":"10.3","page":190,"type":"calc","level":1,"q":"After an irrigation, a set received 12.0 ac-in gross, and 9.5 ac-in infiltrated. Recession is complete. How much ran off?","opts":["0 ac-in","2.5 ac-in","21.5 ac-in","9.5 ac-in"],"a":1,"why":"V_r = V_g − V_z − V_s = 12.0 − 9.5 − 0 = 2.5 ac-in. Surface storage is zero once recession is complete.","eq":"10.1","calc":"eq-10.1","fig":null,"table":null},
  {"id":"10-034","ch":10,"sec":"10.3","page":190,"type":"calc","level":2,"q":"A set received 4.3 in gross, and the average infiltrated depth was 3.6 in. Recession is complete. What percent of the applied water ran off?","opts":["19%","16%","84%","0.7%"],"a":1,"why":"d_r = 4.3 − 3.6 − 0 = 0.7 in, and 0.7 ÷ 4.3 = 16%. 19% divides by the infiltrated depth (0.7 ÷ 3.6), and 84% is the infiltrated share.","eq":"10.2","calc":"eq-10.2","fig":null,"table":null},
  {"id":"10-035","ch":10,"sec":"10.3","page":190,"type":"calc","level":3,"q":"Partway through a set, 3.0 in has been applied, 2.2 in has infiltrated, and 0.3 in is stored on the surface. How much has run off so far?","opts":["0.5 in","0.8 in","1.1 in","0.3 in"],"a":0,"why":"d_r = d_g − d_z − d_s = 3.0 − 2.2 − 0.3 = 0.5 in. During application surface storage is not zero, and ignoring it gives 0.8 in.","eq":"10.2","calc":"eq-10.2","fig":null,"table":null},
  {"id":"10-036","ch":10,"sec":"10.4","page":192,"type":"calc","level":1,"q":"A furrow set had 1.2 in of runoff from a gross application of 4.8 in. What is the runoff ratio R_r?","opts":["0.33","0.20","0.25","4.0"],"a":2,"why":"R_r = d_r ÷ d_g = 1.2 ÷ 4.8 = 0.25 (Eq. 10.8). 4.0 inverts it, and 0.33 divides runoff by the infiltrated depth (1.2 ÷ 3.6).","eq":"10.8","calc":"eq-10.8","fig":null,"table":null},
  {"id":"10-037","ch":10,"sec":"10.4","page":191,"type":"recall","level":1,"q":"What is the return ratio R_t of a runoff recovery system?","opts":["Volume of runoff divided by gross volume applied","Volume applied from the recovery system divided by the volume of runoff","Volume recovered divided by volume infiltrated","Recovery pump flow divided by supply well flow"],"a":1,"why":"R_t is the efficiency of the recovery system: how much of the runoff actually gets reapplied. Runoff ÷ gross applied is the runoff ratio R_r.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-038","ch":10,"sec":"10.4","page":191,"type":"concept","level":2,"q":"In Eq. 10.6 and 10.7, when is the effective depth stored, d_e, equal to SWD instead of d_LQ?","opts":["When d_LQ is greater than SWD, because water beyond the deficit in the low quarter is not stored","When d_LQ is less than SWD","When the system has no runoff recovery","When the runoff ratio is above 0.30"],"a":0,"why":"d_e = d_LQ if d_LQ ≤ SWD, otherwise d_e = SWD. The root zone can only hold the deficit, so extra water percolates below it.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-039","ch":10,"sec":"10.4","page":191,"type":"calc","level":2,"q":"A medium soil furrow field has d_g = 4.33 in, d_LQ = 3.0 in, SWD = 4.0 in and R_r = 0.10. A closed recovery system with R_t = 0.85 is installed. What is E_LQ?","opts":["75%","82%","69%","76%"],"a":3,"why":"E_LQ = d_e ÷ (d_g − d_g R_r R_t) = 3.0 ÷ (4.33 − 4.33 × 0.10 × 0.85) = 3.0 ÷ 3.96 = 76%. 69% is with no recovery (3.0 ÷ 4.33), and 75% uses the open system formula.","eq":"10.6","calc":"eq-10.6-10.7","fig":null,"table":null},
  {"id":"10-040","ch":10,"sec":"10.4","page":191,"type":"calc","level":3,"q":"A set has d_g = 4.0 in, d_LQ = 2.6 in, SWD = 3.0 in and R_r = 0.25. The runoff is pumped to a different field (open system) with R_t = 0.80. What is E_LQ?","opts":["65%","78%","52%","81%"],"a":1,"why":"Open: E_LQ = d_e (1 + R_r R_t) ÷ d_g = 2.6 × (1 + 0.20) ÷ 4.0 = 78%. The closed formula gives 81%, slightly higher because some runoff escapes the second field.","eq":"10.7","calc":"eq-10.6-10.7","fig":null,"table":null},
  {"id":"10-041","ch":10,"sec":"10.4","page":191,"type":"calc","level":3,"q":"A closed recovery system (R_t = 0.85) serves a set with d_g = 6.0 in, d_LQ = 4.0 in, SWD = 3.2 in and R_r = 0.30. What is E_LQ?","opts":["53%","67%","72%","89%"],"a":2,"why":"d_LQ exceeds SWD, so d_e = 3.2 in. E_LQ = 3.2 ÷ (6.0 − 6.0 × 0.30 × 0.85) = 3.2 ÷ 4.47 = 72%. Using d_LQ (4.0 in) gives an inflated 89%.","eq":"10.6","calc":"eq-10.6-10.7","fig":null,"table":null},
  {"id":"10-042","ch":10,"sec":"10.4","page":192,"type":"calc","level":1,"q":"A furrow field without runoff recovery has d_g = 4.0 in, d_LQ = 2.5 in and SWD = 3.0 in. What is E_LQ?","opts":["63%","83%","160%","75%"],"a":0,"why":"With no recovery, E_LQ = d_e ÷ d_g. d_LQ is less than SWD, so d_e = 2.5 in and 2.5 ÷ 4.0 = 63% (rounded). 75% uses SWD as d_e, and 160% inverts the ratio.","eq":"5.11","calc":"eq-5.9-5.11","fig":null,"table":null},
  {"id":"10-043","ch":10,"sec":"10.4","page":192,"type":"calc","level":2,"q":"A furrow infiltration profile gives an average depth of 3.4 in and a low quarter average of 2.6 in. What is the distribution uniformity?","opts":["0.24","0.62","1.31","0.76"],"a":3,"why":"DU = d_LQ ÷ d_z = 2.6 ÷ 3.4 = 0.76 (Eq. 5.2), the same way Example 10.1 gets 0.78. 1.31 inverts the ratio.","eq":"5.2","calc":"eq-5.2","fig":null,"table":null},
  {"id":"10-044","ch":10,"sec":"10.4","page":191,"type":"concept","level":2,"q":"Why is E_LQ for an open runoff recovery system slightly lower than for a closed system with the same R_r and R_t?","opts":["The open system cannot reuse any runoff","The closed system has a larger reservoir","The open system pumps water uphill and loses more to evaporation","Some runoff escapes from the second field that is irrigated with the recovered water"],"a":3,"why":"In the open system the receiving field is allowed to run off, so some recovered water leaves the farm. Example 10.3 gives 76% compared with 78% for the closed system in Example 10.2.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-045","ch":10,"sec":"10.4","page":191,"type":"concept","level":3,"q":"In the closed system formula E_LQ = d_e ÷ (d_g − d_g R_r R_t), what does the denominator represent?","opts":["The depth of runoff that leaves the farm","The depth stored in the root zone","The depth lost to deep percolation","The net depth drawn from the original source, since reused runoff is subtracted from the gross application"],"a":3,"why":"d_g R_r R_t is the depth of runoff returned to the same field. Subtracting it from d_g leaves the water actually supplied by the source, which is the true input for efficiency.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-046","ch":10,"sec":"10.4","page":193,"type":"figure","level":1,"q":"In Figure 10.12, what distinguishes the open runoff recovery system from the closed one?","opts":["The recovery pump sends runoff to a different field instead of back to the field of origin","The open system has no sump","The open system returns water through the original supply well","The open system uses an unlined drainage ditch"],"a":0,"why":"In the closed system a return pipeline carries runoff back to the head of the same field. In the open system the recovery pump delivers it to another field.","eq":null,"calc":null,"fig":"10.12","table":null},
  {"id":"10-047","ch":10,"sec":"10.4","page":193,"type":"recall","level":1,"q":"What range of application efficiency is often reported for field-scale surface irrigation systems?","opts":["40% to 50%","70% to 80%","85% to 95%","20% to 25%"],"a":0,"why":"The book says field-scale efficiencies are often reported to be quite low, 40% to 50%, which motivates the improvement methods it lists.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-048","ch":10,"sec":"10.4","page":193,"type":"concept","level":2,"q":"What is the main benefit of laser and GPS controlled land grading for surface irrigation?","opts":["Automatic shutoff of the water at the end of the set","Higher infiltration rates in the furrows","Improved application uniformity from uniform slopes without high and low spots","Lower seepage from field ditches"],"a":2,"why":"Grading removes low spots, high spots and pot holes and gives uniform slopes, which speeds advance and improves uniformity. Lined ditches and gated pipe are the seepage fix.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-049","ch":10,"sec":"10.4","page":191,"type":"scenario","level":2,"q":"A grower just built a tailwater pit that pumps back to the same field. He asks, \"How do I figure out my new efficiency?\" What two things must you know besides d_g and d_e?","opts":["The field slope and the furrow length","How much runs off (runoff ratio) and how much of that runoff actually gets reapplied (return ratio)","The soil texture and the crop's ET","The pit's depth and the pump's horsepower"],"a":1,"why":"The book says the effect of recovery on efficiency can be found when you know the amount of runoff and the effectiveness of the recovery system, R_r and R_t in Eq. 10.6.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-050","ch":10,"sec":"10.5","page":193,"type":"recall","level":1,"q":"Which three things can a surface irrigator change without changing the system itself?","opts":["Pump size, pipe diameter, and gate spacing","Crop variety, row spacing, and planting date","Field slope, furrow length, and soil texture","Set time, stream size, and the soil water deficit before irrigation"],"a":3,"why":"The book says the irrigator controls set (cutoff) time, stream size, and the SWD at irrigation, and all three can change without altering the system. Slope and length are system characteristics.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-051","ch":10,"sec":"10.5","page":194,"type":"concept","level":2,"q":"Why does the book take a reactive, or adaptive, approach to furrow management rather than computing an optimal set time and stream size in advance?","opts":["Reactive management always gives 90% efficiency","Computer models cannot simulate furrows","Infiltration is seldom known on the day of irrigation, and computed set times often do not fit the labor available","Growers are required by law to measure advance each irrigation"],"a":2,"why":"Optimum combinations need accurate infiltration data for that day, which is almost never available, and model results can be impractical for labor. So the irrigator measures advance and adjusts.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-052","ch":10,"sec":"10.5","page":194,"type":"recall","level":2,"q":"How does a surge valve help with the labor constraint on set time in the Great Plains?","opts":["It runs two 6 hour sets in the 12 hours between visits, so the irrigator returns only once every 12 hours","It shuts off the well when runoff begins","It doubles the furrow stream size during advance","It lets one set run for 24 hours without supervision"],"a":0,"why":"Set times are commonly 6, 12, 18 or 24 hours. A surge valve irrigating two sets alternately allows 6 hour sets while the irrigator still visits every 12 hours, cutting set time by 50%.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-053","ch":10,"sec":"10.5","page":194,"type":"calc","level":1,"q":"A well supplies 900 gpm to a furrow set of 36 furrows. What is the furrow stream size?","opts":["25 gpm","36 gpm","32,400 gpm","0.04 gpm"],"a":0,"why":"q_s = Q_t ÷ N = 900 ÷ 36 = 25 gpm per furrow (Eq. 10.9). With a fixed supply, changing the number of furrows is how the irrigator changes stream size.","eq":"10.9","calc":"eq-10.9","fig":null,"table":null},
  {"id":"10-054","ch":10,"sec":"10.5","page":194,"type":"calc","level":1,"q":"What is the approximate maximum nonerosive furrow stream size on a 0.25% slope?","opts":["4 gpm","40 gpm","2.5 gpm","25 gpm"],"a":1,"why":"q_max = 10 ÷ S with S in percent: 10 ÷ 0.25 = 40 gpm (Eq. 10.10). 2.5 gpm multiplies instead of dividing, and 25 gpm is the value for a 0.4% slope.","eq":"10.10","calc":"eq-10.10","fig":null,"table":null},
  {"id":"10-055","ch":10,"sec":"10.5","page":194,"type":"calc","level":2,"q":"A grower plans 20 gpm per furrow on a field with a 0.6% slope. Is the stream within the nonerosive limit?","opts":["Yes, the limit is about 60 gpm","Yes, the limit is about 33 gpm","No, the limit is about 6 gpm","No, the limit is about 17 gpm, so 20 gpm risks erosion"],"a":3,"why":"q_max = 10 ÷ 0.6 = 16.7 gpm, so 20 gpm exceeds it. 33 gpm is the limit at 0.3% slope. NRCS velocity guidelines are more specific, but Eq. 10.10 flags the problem.","eq":"10.10","calc":"eq-10.10","fig":null,"table":null},
  {"id":"10-056","ch":10,"sec":"10.5","page":194,"type":"recall","level":1,"q":"What is the largest soil water deficit an irrigator should allow before irrigating, if he wants to raise SWD to improve surface irrigation efficiency?","opts":["The total available water in the root zone","The permanent wilting point","The management allowed deficit (AD)","Field capacity"],"a":2,"why":"SWD can be increased by irrigating less often, but only up to AD, beyond which yield suffers.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-057","ch":10,"sec":"10.5","page":195,"type":"calc","level":1,"q":"Water reaches the end of a furrow in 7.2 hours on a 12 hour set. What is the cutoff ratio?","opts":["1.67","4.8","0.40","0.60"],"a":3,"why":"CR = t_L ÷ t_co = 7.2 ÷ 12 = 0.60 (Eq. 10.11). 1.67 inverts the ratio, and 4.8 is the time remaining after advance.","eq":"10.11","calc":"eq-10.11","fig":null,"table":null},
  {"id":"10-058","ch":10,"sec":"10.5","page":195,"type":"concept","level":2,"q":"What happens to runoff and uniformity as the cutoff ratio gets lower?","opts":["Runoff decreases and deep percolation increases","Runoff increases and uniformity improves","Runoff decreases and uniformity improves","Runoff increases and uniformity gets worse"],"a":1,"why":"A low cutoff ratio means fast advance relative to set time, so opportunity times are more even but much water runs off. High ratios give low runoff, poor distribution and high deep percolation.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-059","ch":10,"sec":"10.5","page":195,"type":"figure","level":1,"q":"In the conceptual Figure 10.13, what loss increases as the cutoff ratio moves to the right of the optimum?","opts":["Seepage from the head ditch","Runoff","Evaporation","Deep percolation"],"a":3,"why":"The arrow to the right is labeled increasing deep percolation, and the arrow to the left is increasing runoff. Maximum E_LQ is where their sum is smallest, at about 0.65 in the sketch.","eq":null,"calc":null,"fig":"10.13","table":null},
  {"id":"10-060","ch":10,"sec":"10.5","page":195,"type":"recall","level":2,"q":"For Figures 10.14 to 10.16, which soils does the book class as medium textured?","opts":["Silts, silt loams, loams and sandy clays","Sandy clay loams, sandy loams, loamy fine sand and fine sand","Loamy sands, sands and gravels","Clays, silty clays, silty clay loams and clay loams"],"a":0,"why":"Medium soils are silts, silt loams, loams and sandy clays. The clays and clay loams are fine, and the sandy loams and fine sands are coarse.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-061","ch":10,"sec":"10.5","page":195,"type":"concept","level":3,"q":"Figures 10.14 to 10.16 assume advance time exceeds recession time. When might that assumption fail?","opts":["On fields with inadequate slope or short furrows, such as smallholder farms, where border or basin principles may apply instead","Whenever a runoff recovery system is used","Whenever the set time is 12 hours or longer","On long, sloping furrows with high infiltration"],"a":0,"why":"The book says the assumption holds for most long, sloping furrows but may not on low slope or short fields. In those cases the principles of Section 10.6 may be more appropriate.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-062","ch":10,"sec":"10.5","page":196,"type":"figure","level":2,"q":"From Figure 10.15 (medium soils), what is the highest E_LQ with closed runoff recovery and at about what cutoff ratio?","opts":["About 70% at a cutoff ratio of about 0.65","About 81% at a cutoff ratio of about 0.5","About 61% at a cutoff ratio of 1.0","About 85% at a cutoff ratio of about 0.4"],"a":3,"why":"The closed curve peaks near 85% around CR 0.4. 70% at 0.65 is the no-recovery peak, 81% at 0.5 is the open system peak, and all curves meet near 61% at CR 1.0.","eq":null,"calc":null,"fig":"10.15","table":null},
  {"id":"10-063","ch":10,"sec":"10.5","page":196,"type":"figure","level":2,"q":"From Figure 10.15, a medium soil field with no runoff recovery runs at a cutoff ratio of 0.4. About what E_LQ should the grower expect?","opts":["About 45%","About 85%","About 62%","About 70%"],"a":2,"why":"The no-recovery curve reads about 62% at CR 0.4. Its peak of about 70% is near CR 0.65 to 0.7, so with no reuse he should slow the advance, not speed it up.","eq":null,"calc":null,"fig":"10.15","table":null},
  {"id":"10-064","ch":10,"sec":"10.5","page":195,"type":"figure","level":2,"q":"From Figure 10.14 (fine soils), at about what cutoff ratio does E_LQ peak for a system with no runoff recovery?","opts":["About 0.9","About 0.7","About 0.2","About 0.5"],"a":0,"why":"The no-recovery curve for fine soils keeps rising to a peak of about 73% near CR 0.85 to 0.9, consistent with the 0.90 in Table 10.5. The closed system peaks near 0.5.","eq":null,"calc":null,"fig":"10.14","table":null},
  {"id":"10-065","ch":10,"sec":"10.5","page":196,"type":"figure","level":2,"q":"From Figure 10.16 (coarse soils), where does the closed runoff recovery curve peak?","opts":["About 82% near a cutoff ratio of 0.4","About 72% near a cutoff ratio of 0.5","About 85% near a cutoff ratio of 0.7","About 87% near a cutoff ratio of 0.2"],"a":3,"why":"On coarse soils the closed curve is highest, about 87%, near CR 0.2. 82% near 0.4 is the open system peak and 72% near 0.5 is the no-recovery peak.","eq":null,"calc":null,"fig":"10.16","table":null},
  {"id":"10-066","ch":10,"sec":"10.5","page":196,"type":"figure","level":3,"q":"In Figure 10.16, why do the three curves converge at a cutoff ratio of 1.0?","opts":["At CR 1.0 the soil is saturated everywhere","At CR 1.0 runoff is greatest, so all recovery systems are full","At CR 1.0 water just reaches the end when it is shut off, so there is almost no runoff to recover","At CR 1.0 deep percolation is zero"],"a":2,"why":"When advance takes the whole set time, little or no water runs off, so recovering runoff adds nothing and all three systems have the same E_LQ, about 54% on coarse soil.","eq":null,"calc":null,"fig":"10.16","table":null},
  {"id":"10-067","ch":10,"sec":"10.5","page":195,"type":"calc","level":1,"q":"A medium soil field with an open reuse system should run at a cutoff ratio of 0.5 (Table 10.5). With 12 hour sets, what advance time should the irrigator aim for?","opts":["24 hours","8.4 hours","6.0 hours","4.8 hours"],"a":2,"why":"t_L = CR × t_co = 0.5 × 12 = 6.0 hours. 8.4 hours is the no-reuse target (0.7) and 4.8 hours the closed reuse target (0.4).","eq":"10.11","calc":"eq-10.11","fig":null,"table":null},
  {"id":"10-068","ch":10,"sec":"10.5","page":197,"type":"table","level":1,"q":"From Table 10.2, what is the correction factor N2/N1 for a medium soil when the desired advance time is half the original (T_L2/T_L1 = 0.5)?","opts":["1.0","0.6","0.5","0.7"],"a":1,"why":"For T_L2/T_L1 = 0.5 the factors are 0.5 fine, 0.6 medium and 0.7 coarse. Halving advance time does not simply halve the furrow count.","eq":null,"calc":null,"fig":null,"table":"10.2"},
  {"id":"10-069","ch":10,"sec":"10.5","page":197,"type":"table","level":2,"q":"A coarse soil set of 50 furrows advanced in 8 hours. The grower wants a 4 hour advance with the same total flow. Using Table 10.2, how many furrows should he water per set?","opts":["100 furrows","25 furrows","35 furrows","30 furrows"],"a":2,"why":"T_L2/T_L1 = 4 ÷ 8 = 0.5, and the coarse factor is 0.7, so N2 = 0.7 × 50 = 35. 25 uses the fine soil factor (0.5), and 100 increases furrows, which slows advance.","eq":null,"calc":"tab-10.2","fig":null,"table":"10.2"},
  {"id":"10-070","ch":10,"sec":"10.5","page":197,"type":"table","level":3,"q":"On a medium soil, 40 furrows advanced in 8 hours with no runoff recovery, and the grower wants a 12 hour advance on a longer set. Using Table 10.2, how many furrows should he water?","opts":["60 furrows","27 furrows","64 furrows","56 furrows"],"a":3,"why":"T_L2/T_L1 = 12 ÷ 8 = 1.5, medium factor 1.4, so N2 = 1.4 × 40 = 56. More furrows means a smaller stream and slower advance. 60 assumes advance scales one to one, and 27 divides.","eq":null,"calc":"tab-10.2","fig":null,"table":"10.2"},
  {"id":"10-071","ch":10,"sec":"10.5","page":197,"type":"table","level":1,"q":"From Table 10.3, what is the infiltration factor (d_LQ/d_g) for a medium soil at a cutoff ratio of 0.4?","opts":["0.71","0.62","0.32","0.51"],"a":1,"why":"Medium soil at CR 0.4 is 0.62, the value used in Examples 10.4 and 10.5. 0.51 is fine, 0.71 is coarse, and 0.32 is the medium runoff ratio from Table 10.4.","eq":null,"calc":null,"fig":null,"table":"10.3"},
  {"id":"10-072","ch":10,"sec":"10.5","page":197,"type":"calc","level":2,"q":"A medium soil furrow set had a gross application of 4.33 in and a cutoff ratio of 0.75. Using Table 10.3 (interpolate), what is the low quarter depth?","opts":["2.9 in","3.0 in","4.3 in","0.43 in"],"a":1,"why":"Between CR 0.7 (0.70) and 0.8 (0.69) the factor is 0.695, so d_LQ = 0.695 × 4.33 = 3.0 in (Eq. 10.12). 0.43 in multiplies by the runoff ratio column instead.","eq":"10.12","calc":"eq-10.12","fig":null,"table":null},
  {"id":"10-073","ch":10,"sec":"10.5","page":197,"type":"calc","level":3,"q":"A fine textured (clay loam) furrow set applies 5.0 in gross at a cutoff ratio of 0.45. Using Table 10.3, what is the low quarter depth?","opts":["3.2 in","2.1 in","2.8 in","3.6 in"],"a":2,"why":"Interpolate fine soil factors 0.51 (CR 0.4) and 0.59 (CR 0.5): 0.55. d_LQ = 0.55 × 5.0 = 2.75, about 2.8 in. 3.2 in uses the medium column (about 0.64).","eq":"10.12","calc":"eq-10.12","fig":null,"table":null},
  {"id":"10-074","ch":10,"sec":"10.5","page":197,"type":"table","level":1,"q":"From Table 10.4, what is the runoff ratio for a coarse soil at a cutoff ratio of 0.3?","opts":["0.56","0.26","0.68","0.42"],"a":1,"why":"Coarse at CR 0.3 is 0.26. Medium is 0.42 and fine is 0.56. 0.68 is the coarse infiltration factor in Table 10.3.","eq":null,"calc":null,"fig":null,"table":"10.4"},
  {"id":"10-075","ch":10,"sec":"10.5","page":197,"type":"table","level":3,"q":"A medium soil set applies 5.0 in gross at a cutoff ratio of 0.6. Using Table 10.4, about how much runs off?","opts":["1.4 in","0.2 in","0.9 in","3.5 in"],"a":2,"why":"R_r = 0.18 for medium soil at CR 0.6, so d_r = 0.18 × 5.0 = 0.9 in. 1.4 in uses the fine soil ratio (0.28), and 3.5 in uses the infiltration factor 0.69.","eq":null,"calc":"tab-10.3-10.4","fig":null,"table":"10.4"},
  {"id":"10-076","ch":10,"sec":"10.5","page":199,"type":"table","level":1,"q":"From Table 10.5, what cutoff ratio gives maximum efficiency for a medium soil with a closed reuse system?","opts":["0.40","0.50","0.20","0.70"],"a":0,"why":"Medium closed reuse is 0.40. No reuse is 0.70, open reuse 0.50, and 0.20 is coarse closed reuse.","eq":null,"calc":null,"fig":null,"table":"10.5"},
  {"id":"10-077","ch":10,"sec":"10.5","page":199,"type":"table","level":2,"q":"A coarse soil field with blocked ends on a 0.5% slope runs 12 hour sets. Using Table 10.5, what advance time gives maximum efficiency?","opts":["7.8 hours","2.4 hours","8.4 hours","6.0 hours"],"a":0,"why":"Blocked ends, moderate slope, coarse soil is CR 0.65, so t_L = 0.65 × 12 = 7.8 hours. 8.4 hours uses the low slope value (0.70), and 6.0 hours is coarse with no reuse (0.50).","eq":null,"calc":"tab-10.5","fig":null,"table":"10.5"},
  {"id":"10-078","ch":10,"sec":"10.5","page":199,"type":"concept","level":3,"q":"Why are recommended cutoff ratios higher when furrow ends are blocked than when they are open?","opts":["Blocked ends increase runoff, which must be offset","Blocked ends speed up the advance","A later advance keeps the pond behind the dike small, limiting deep percolation beneath it","Higher ratios are needed to fill the tail ditch"],"a":2,"why":"Water ponds behind the dike and over-irrigates that area (Figure 10.17). Shutting off soon after water reaches the end minimizes the pond and its deep percolation.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-079","ch":10,"sec":"10.5","page":199,"type":"figure","level":2,"q":"What does the infiltration profile for blocked-end furrows in Figure 10.17 show?","opts":["Infiltration decreases down the furrow, then increases sharply in the pond near the diked end","Infiltration increases steadily from inlet to end","Infiltration is uniform along the whole furrow","Infiltration is highest at the inlet and zero at the diked end"],"a":0,"why":"The curve gets shallower with distance like an open furrow, then jumps deeper in the reach where water ponds behind the dike. That pond causes extra deep percolation.","eq":null,"calc":null,"fig":"10.17","table":null},
  {"id":"10-080","ch":10,"sec":"10.5","page":199,"type":"table","level":1,"q":"From Table 10.6, what is the maximum recommended furrow length on a loamy sand?","opts":["1,300 ft","800 ft","600 ft","1,000 ft"],"a":2,"why":"Loamy sand is limited to 600 ft because of its high intake (2.0 to 5.0 in/hr). Sandy loam allows 800 ft and silty clay loam 1,300 ft.","eq":null,"calc":null,"fig":null,"table":"10.6"},
  {"id":"10-081","ch":10,"sec":"10.5","page":199,"type":"table","level":2,"q":"Using Table 10.6, what furrow stream size is recommended for a 1,100 ft silt loam furrow?","opts":["41.8 gpm","24.2 gpm","12.1 gpm","2.2 gpm"],"a":1,"why":"Silt loam recommends 2.2 gpm per 100 ft: 2.2 × 11 = 24.2 gpm. 12.1 gpm uses the basic infiltration rate (1.1 gpm/100 ft), which is what the furrow absorbs, not what it needs to advance.","eq":null,"calc":"tab-10.6","fig":null,"table":"10.6"},
  {"id":"10-082","ch":10,"sec":"10.5","page":199,"type":"concept","level":2,"q":"About how does watering every other furrow change infiltration and advance time for the same stream size?","opts":["Infiltration drops about 50% and advance time is unchanged","Infiltration increases about 25% and advance time drops about 30%","Infiltration drops about 25% to 30% and advance time increases about 30% to 40%","Infiltration is unchanged and advance time doubles"],"a":2,"why":"The book gives a 25% to 30% reduction in infiltration and a 30% to 40% longer advance, because wetting fronts between watered furrows take longer to meet.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-083","ch":10,"sec":"10.5","page":199,"type":"concept","level":3,"q":"Advance is slower with every other furrow irrigation. Why does it still usually reduce the depth applied?","opts":["Every other furrow seals the soil surface","The set covers twice as many rows, so the same flow is spread over twice the area","Every other furrow eliminates runoff","Every other furrow increases the stream size per furrow"],"a":1,"why":"Even with a longer advance, the set size is twice as large as with every furrow watered, so the gross depth (Eq. 10.4 with W doubled) and infiltration go down.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-084","ch":10,"sec":"10.5","page":199,"type":"calc","level":2,"q":"A furrow advances in 8 hours when every furrow is watered. Using the book's estimate, about how long will advance take with every other furrow at the same stream size?","opts":["About 8 hours","About 5.6 to 6.0 hours","About 16 hours","About 10.4 to 11.2 hours"],"a":3,"why":"Every other furrow increases advance time about 30% to 40%: 8 × 1.3 = 10.4 and 8 × 1.4 = 11.2 hours. 5.6 to 6.0 hours applies the infiltration reduction to advance time.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-085","ch":10,"sec":"10.5","page":200,"type":"concept","level":3,"q":"An irrigator can only return every 12 hours but wants 8 hour sets, so he puts the water on a timer. What is the limitation?","opts":["Runoff will increase by 50%","Timers cannot be used with gated pipe","System capacity must be large enough to cover the 4 hours of down time before he returns","The cutoff ratio will be above 1.0"],"a":2,"why":"Shutting off at 8 hours leaves the system idle until the next visit. Chapter 5 capacity must allow for that down time or the crop falls behind.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-086","ch":10,"sec":"10.5","page":200,"type":"recall","level":1,"q":"If infiltration rates are too high to reach the desired efficiency, what field practice does the book suggest?","opts":["Furrow packing and smoothing with special tillage tools","Planting a cover crop in the furrows","Deep ripping the furrows","Adding gypsum to the irrigation water"],"a":0,"why":"Packing and smoothing the furrow with special tools lowers intake and speeds advance. Land smoothing and laser grading also improve advance and uniformity.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-087","ch":10,"sec":"10.5","page":197,"type":"calc","level":2,"q":"A furrow irrigation stores an effective depth of 2.4 in, and the crop uses 0.28 in/day. About how many days should the irrigator wait before the next irrigation?","opts":["About 0.67 days","About 8.6 days","About 12 days","About 6.7 days"],"a":1,"why":"Interval = d_e ÷ ET = 2.4 ÷ 0.28 = 8.6 days. The schedule follows the effective water applied, as in the book's example of 2.9 in at 0.3 in/day giving about 10 days.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-088","ch":10,"sec":"10.5","page":197,"type":"table","level":2,"q":"A medium soil field gets 900 gpm. A trial set of 60 furrows advanced in 8 hours on 12 hour sets. With closed reuse, the target cutoff ratio is 0.4. Using Table 10.2, how many furrows should be watered per set?","opts":["30 furrows","42 furrows","86 furrows","36 furrows"],"a":1,"why":"Target t_L = 0.4 × 12 = 4.8 hours. T_L2/T_L1 = 4.8 ÷ 8 = 0.6, medium factor 0.7, N2 = 0.7 × 60 = 42. 36 uses 0.6 directly as the factor, and 86 divides.","eq":null,"calc":"proc-furrow-set","fig":null,"table":"10.2"},
  {"id":"10-089","ch":10,"sec":"10.5","page":198,"type":"calc","level":3,"q":"The 900 gpm field is changed to 42 furrows per set on 30 in rows, every furrow, 1,000 ft long, 12 hour sets. What is the gross application depth, and is it a concern?","opts":["2.5 in, too little to refill the root zone","9.9 in, far more than a typical deficit, so d_LQ will exceed SWD","4.9 in, about right for a 3.5 in deficit","6.6 in, acceptable with closed reuse"],"a":1,"why":"d_g = 1155 × 900 × 12 ÷ (42 × 30 × 1,000) = 9.9 in. With an infiltration factor of 0.62, d_LQ is about 6.1 in, far over a 3.5 in SWD, which is the trap shown in Example 10.4.","eq":"10.4","calc":"proc-furrow-set","fig":null,"table":null},
  {"id":"10-090","ch":10,"sec":"10.5","page":198,"type":"calc","level":3,"q":"For a closed reuse system (R_t = 0.85) on medium soil at CR 0.4, d_g = 9.9 in, d_LQ = 6.1 in, SWD = 3.5 in and R_r = 0.32 (Table 10.4). What is E_LQ?","opts":["35%","85%","62%","49%"],"a":3,"why":"d_LQ exceeds SWD, so d_e = 3.5 in. E_LQ = 3.5 ÷ (9.9 − 9.9 × 0.32 × 0.85) = 3.5 ÷ 7.21 = 49%. Using d_LQ gives 85%, the curve value that only applies when d_LQ is below SWD.","eq":"10.6","calc":"proc-furrow-set","fig":null,"table":null},
  {"id":"10-091","ch":10,"sec":"10.5","page":198,"type":"calc","level":3,"q":"A medium soil set with closed reuse runs at CR 0.4 with d_g = 4.6 in and SWD = 3.0 in. The recovery system returns only 70% of the runoff (R_t = 0.70). Using Tables 10.3 and 10.4, what is E_LQ?","opts":["85%","80%","62%","75%"],"a":1,"why":"d_LQ = 0.62 × 4.6 = 2.85 in (below SWD, so d_e = 2.85). R_r = 0.32. E_LQ = 2.85 ÷ (4.6 − 4.6 × 0.32 × 0.70) = 2.85 ÷ 3.57 = 80%. 85% assumes R_t = 0.85, and 62% ignores the recovery.","eq":"10.6","calc":"eq-10.6-10.7","fig":null,"table":null},
  {"id":"10-092","ch":10,"sec":"10.5","page":198,"type":"calc","level":3,"q":"Example 10.5 cut the set time to 6 hours on 760 gpm with 30 in furrow spacing, 1,200 ft long. If the grower waters 30 furrows per set instead of 26, what is the gross depth?","opts":["4.2 in","5.6 in","4.9 in","9.8 in"],"a":2,"why":"d_g = 1155 × 760 × 6 ÷ (30 × 30 × 1,200) = 4.88, about 4.9 in. 5.6 in is the arithmetic for 26 furrows (the book prints 5.0 in for that case, but 1155 × 760 × 6 ÷ 936,000 = 5.6 in), and 9.8 in is a 12 hour set.","eq":"10.4","calc":"proc-furrow-set","fig":null,"table":null},
  {"id":"10-093","ch":10,"sec":"10.5","page":198,"type":"scenario","level":3,"q":"A grower's tailwater pit is working, but his low quarter depth (4.1 in) is above his soil water deficit (3.4 in), and the deficit is already at the allowable depletion. What should he try?","opts":["Wait longer between irrigations so the deficit grows past AD","Increase the number of furrows per set to reach a cutoff ratio of 1.0","Shorten the set time or water every other furrow to reduce the depth infiltrated","Remove the tailwater pit to cut the gross application"],"a":2,"why":"When d_LQ > SWD and SWD already equals AD, the book says reduce infiltrated depth with shorter set times or every other furrow, as Example 10.5 did with a 6 hour set. Waiting past AD costs yield.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-094","ch":10,"sec":"10.5","page":196,"type":"scenario","level":3,"q":"A grower on a silt loam with a tailwater return pit says, \"I can only change sets every 12 hours. How fast should the water get to the end?\"","opts":["About 8.4 hours, a cutoff ratio of 0.7","About 1 hour, as fast as possible","About 12 hours, so there is no runoff","About 4.8 hours, a cutoff ratio of 0.4, then adjust furrows per set to hit it"],"a":3,"why":"Silt loam is medium textured, and with closed reuse the best cutoff ratio is about 0.4 (Figure 10.15, Table 10.5), so t_L = 0.4 × 12 = 4.8 hours. 8.4 hours is the no-reuse target.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-095","ch":10,"sec":"10.5","page":196,"type":"scenario","level":2,"q":"A grower says, \"On my 12 hour sets the water takes 14 hours to reach the end.\" What should he change first?","opts":["Extend the set to 24 hours and block the ends","Leave it, since a cutoff ratio above 1.0 is ideal","Water more furrows per set to slow the water down","Water fewer furrows per set to raise the stream size, staying under the nonerosive limit"],"a":3,"why":"Advance longer than the set means the tail never gets water. Fewer furrows with the same supply raises q_s (Eq. 10.9) and speeds advance, as long as q_s stays under q_max (Eq. 10.10).","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-096","ch":10,"sec":"10.5","page":196,"type":"scenario","level":3,"q":"A grower on loam with no tailwater recovery says, \"My water hits the end in 2 hours on 12 hour sets and runs off all night.\" What do you advise?","opts":["Water more furrows per set to slow advance toward about 8.4 hours (cutoff ratio about 0.7)","Keep the set and add a dike, since loam is ideal for blocked ends at this slope","Shorten the set to 3 hours with the same furrows","Water fewer furrows per set to speed advance even more"],"a":0,"why":"CR = 2 ÷ 12 = 0.17, far below the no-reuse optimum of about 0.7 for medium soil, so runoff is huge. More furrows per set lowers the stream and slows advance toward 0.7 × 12 = 8.4 hours.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-097","ch":10,"sec":"10.5","page":197,"type":"scenario","level":3,"q":"A medium soil field gets 900 gpm on 40 furrows, and advance takes 9 hours on 12 hour sets. The grower adds closed reuse and wants CR 0.4. Table 10.2 says water about 25 furrows. The slope is 0.3%. What do you tell him?","opts":["Cutoff ratio does not depend on furrows per set","25 furrows gives 36 gpm per furrow, above the 33 gpm nonerosive limit, so use about 28 furrows or shorter runs and accept a slightly higher cutoff ratio","25 furrows is fine because closed reuse catches any eroded soil","Water 60 furrows to reach CR 0.4"],"a":1,"why":"Ratio 4.8 ÷ 9 = 0.53 gives about 0.63 × 40 = 25 furrows, and q_s = 900 ÷ 25 = 36 gpm, but q_max = 10 ÷ 0.3 = 33 gpm. The stream limit can block the ideal cutoff ratio, so stay at or below 33 gpm (about 28 furrows).","eq":"10.10","calc":"proc-furrow-set","fig":null,"table":null},
  {"id":"10-098","ch":10,"sec":"10.5","page":199,"type":"scenario","level":2,"q":"A grower irrigating a new sandy loam field for the first time asks how long his furrows can be and how much water each needs. What do you use?","opts":["Table 10.7: a cycle 1 factor of 1.0","Table 10.5: a cutoff ratio of 0.50","Table 10.6: up to 800 ft, about 3.8 gpm per 100 ft, checked against the nonerosive stream size","Table 10.2: a correction factor of 1.0"],"a":2,"why":"For a first irrigation with no advance data, Table 10.6 keeps flow, advance and length in a reasonable range. Sandy loam allows 800 ft and 3.8 gpm/100 ft, but the stream must stay below q_max.","eq":null,"calc":null,"fig":null,"table":"10.6"},
  {"id":"10-099","ch":10,"sec":"10.5","page":199,"type":"scenario","level":3,"q":"A grower has 800 ft sandy loam furrows on a 0.5% slope and plans to use the Table 10.6 stream size. What is the problem?","opts":["The slope is too flat for sandy loam","There is no problem, since 800 ft is the maximum length","Table 10.6 gives 30.4 gpm, but the nonerosive limit at 0.5% is 20 gpm, so he should shorten the furrows","The stream is too small, since sandy loam needs 48 gpm"],"a":2,"why":"3.8 gpm/100 ft × 8 = 30.4 gpm, but q_max = 10 ÷ 0.5 = 20 gpm. The footnote says the stream must be below the nonerosive limit, and the book's fix when q_max limits is a shorter furrow.","eq":null,"calc":"tab-10.6","fig":null,"table":"10.6"},
  {"id":"10-100","ch":10,"sec":"10.5","page":200,"type":"scenario","level":2,"q":"A grower can only get to the field every 12 hours, but his best cutoff ratio calls for an 8 hour set. Which options does the book offer?","opts":["Run 12 hour sets and block the furrow ends","Run 8 hour sets and let runoff continue for 4 hours","Double the number of furrows per set","A timer to shut the water off at 8 hours, if system capacity allows the down time, or a surge valve for semi-automation"],"a":3,"why":"Automation or semi-automation removes the set time constraint. A timer works if capacity covers the off time, and a surge valve can run two sets in a 12 hour visit cycle.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-101","ch":10,"sec":"10.5","page":200,"type":"concept","level":1,"q":"How does land smoothing or laser grading improve surface irrigation?","opts":["It removes high spots, low spots and pot holes, giving a uniform slope that speeds advance and improves uniformity","It steepens the slope above 2%","It eliminates the need for a set time","It increases the infiltration rate of the soil"],"a":0,"why":"A uniform surface slope keeps water from collecting in depressions, which increases the advance rate and uniformity of application.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-102","ch":10,"sec":"10.6","page":200,"type":"concept","level":2,"q":"Why are high stream sizes and short set times appropriate for level basins?","opts":["Short sets keep the basin from overflowing the dikes","High streams reduce evaporation from the basin","Basins are always on sandy soils","Dikes retain all the water so there is no runoff, and deep percolation is the only loss"],"a":3,"why":"With level bottoms and dikes, no water runs off. A fast fill gives even opportunity time, which reduces deep percolation, the only remaining loss.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-103","ch":10,"sec":"10.6","page":200,"type":"recall","level":1,"q":"For which crops does the book say basin and border systems are often more appropriate than furrows?","opts":["Rice only","Closely spaced crops like alfalfa and orchard crops","Wide row crops like corn and cotton","Vegetables on raised beds"],"a":1,"why":"Basins and borders suit closely spaced crops such as alfalfa and orchards. Furrows are sometimes used in level basins with row crops.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-104","ch":10,"sec":"10.6","page":200,"type":"concept","level":3,"q":"Why might the sloping furrow cutoff ratio guidelines fail on a border strip in dense alfalfa?","opts":["Vegetation resistance stores a lot of water on the surface, so recession can be slow and even exceed advance time","Alfalfa roots raise infiltration so advance never ends","Borders have no slope in the direction of flow","Borders cannot have runoff"],"a":0,"why":"Flow resistance holds water on the surface, giving long recession that can exceed advance, which breaks the assumption behind Figures 10.14 to 10.16. Sometimes the best practice is to cut off before advance is complete.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-105","ch":10,"sec":"10.6","page":200,"type":"recall","level":1,"q":"Which simulation model does the book suggest for developing management strategies for basins and borders?","opts":["AquaCrop","WinSRFR","CROPWAT","HYDRUS"],"a":1,"why":"The book points to WinSRFR (Bautista et al., 2012) for optimizing basin and border management at a specific site.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-106","ch":10,"sec":"10.6","page":200,"type":"scenario","level":3,"q":"An alfalfa grower with sloping borders says, \"Water keeps sheeting down the border for hours after I shut it off and floods the low end.\" What do you suggest?","opts":["Try cutting off inflow before advance reaches the end, since recession is slow, and check the plan with a model such as WinSRFR","Use the sloping furrow cutoff ratio of 0.7 from Table 10.5","Reduce the border slope to zero","Keep inflow on until water ponds at the end, as for blocked furrows"],"a":0,"why":"With dense vegetation, surface storage is large and recession can exceed advance. The book notes optimal management is sometimes to stop inflow before advance is complete.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-107","ch":10,"sec":"10.7","page":200,"type":"concept","level":2,"q":"Why is runoff an inherent problem with sloping furrow and border irrigation?","opts":["Water must stay at the downstream end long enough for uniform infiltration, which creates runoff","Surface storage cannot infiltrate","Gated pipe always delivers more water than the soil can take","Runoff is needed to flush salts"],"a":0,"why":"Uniform infiltration needs adequate opportunity time at the tail, and on an open-ended slope that means water flows off while it is there.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-108","ch":10,"sec":"10.7","page":201,"type":"concept","level":2,"q":"What is the drawback of blocking furrow ends on a field whose slope is too steep?","opts":["Runoff increases","Advance becomes much slower","The dike prevents water from reaching the end","Ponded water covers only a small area and infiltrates there, giving poor distribution"],"a":3,"why":"On low slopes the backed-up water spreads over a large area. On steeper slopes it stays near the end, over-irrigating a small area. Long submergence can also hurt sensitive crops.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-109","ch":10,"sec":"10.7","page":201,"type":"recall","level":2,"q":"In cutback irrigation, to what rate is inflow reduced after advance is complete?","opts":["Zero, for a recovery period","Half the original stream size","About the steady-state infiltration rate of the wetted area","The maximum nonerosive stream size"],"a":2,"why":"Cutback uses a large stream for advance, then reduces it to roughly what the wetted furrow takes in at steady state. Estimating that rate takes experience.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-110","ch":10,"sec":"10.7","page":201,"type":"concept","level":3,"q":"When does runoff recovery save pumping energy?","opts":["Only when the recovery pump is solar powered","Only when the runoff goes to another field","When the total dynamic head to pump the runoff is less than the head for the original supply","Always, because runoff water is free"],"a":2,"why":"If the original supply is pumped, reusing runoff saves energy only when lifting the runoff takes less head than pumping new water, which is common with deep wells.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-111","ch":10,"sec":"10.7","page":201,"type":"recall","level":1,"q":"In a runoff recovery system, what is the purpose of the desilting basin at the sump or reservoir inlet?","opts":["To settle sediment out of the runoff water","To measure the runoff volume","To remove trash from the water","To prevent erosion where water drops into the sump"],"a":0,"why":"Inlet facilities include a desilting basin to settle sediment, screens to remove trash, and a chute, drop or pipe inlet to deliver water without serious erosion.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-112","ch":10,"sec":"10.7","page":201,"type":"recall","level":1,"q":"For a continuous-pump runoff recovery system, what is the reservoir designed to hold?","opts":["The runoff from one irrigation set, plus freeboard and dead storage","The full volume applied to one set","The runoff from an entire season","The runoff from two or more sets"],"a":0,"why":"The continuous system stores one set's runoff and pumps at the time averaged runoff rate. Storing two or more sets is the intermittent design.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-113","ch":10,"sec":"10.7","page":201,"type":"recall","level":2,"q":"Typically, what share of the volume applied to one set does a recovery reservoir need to store?","opts":["20% to 55%","60% to 80%","100%","5% to 10%"],"a":0,"why":"The book says required storage typically runs 20% to 55% of the volume applied to one set, depending on field and management.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-114","ch":10,"sec":"10.7","page":202,"type":"recall","level":2,"q":"What runoff ratio does the book suggest using to design recovery reservoirs and pumps?","opts":["A low estimate, 0.05 to 0.10","The average from Table 10.4, about 0.20","Exactly the value measured in the first irrigation","A high estimate, 0.30 to 0.40"],"a":3,"why":"Even though the equations have some safety margin from seepage and evaporation, the book recommends an additional margin by using a high R_r of 0.30 to 0.40.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-115","ch":10,"sec":"10.7","page":202,"type":"calc","level":2,"q":"A continuous-pump recovery system returns runoff to the field of origin (F = 1). Q_w = 800 gpm, t_co = 720 min and design R_r = 0.35. What reservoir volume is needed?","opts":["About 310,000 gal (11.4 ac-in)","About 431 gal (0.02 ac-in)","About 202,000 gal (7.4 ac-in)","About 576,000 gal (21.2 ac-in)"],"a":0,"why":"V_r = R_r t_co Q_w ÷ (1 − R_r F) = 0.35 × 720 × 800 ÷ 0.65 = 310,154 gal, and ÷ 27,154 gal/ac-in = 11.4 ac-in. 202,000 gal uses F = 0, which ignores the extra runoff from recycled water.","eq":"10.13","calc":"eq-10.13-10.14","fig":null,"table":null},
  {"id":"10-116","ch":10,"sec":"10.7","page":202,"type":"calc","level":2,"q":"For the same system (Q_w = 800 gpm, R_r = 0.35, F = 1), what recovery pump capacity is needed?","opts":["About 280 gpm","About 431 gpm","About 1,231 gpm","About 520 gpm"],"a":1,"why":"Q_r = R_r Q_w ÷ (1 − R_r F) = 0.35 × 800 ÷ 0.65 = 431 gpm (Eq. 10.14). 280 gpm is the F = 0 answer, used when runoff goes to another field.","eq":"10.14","calc":"eq-10.13-10.14","fig":null,"table":null},
  {"id":"10-117","ch":10,"sec":"10.7","page":202,"type":"calc","level":3,"q":"A recovery system delivers runoff to another field (F = 0). Q_w = 600 gpm, t_co = 12 hr and design R_r = 0.30. What reservoir volume is needed?","opts":["185,100 gal","2,160 gal","129,600 gal","432,000 gal"],"a":2,"why":"V_r = 0.30 × 720 min × 600 gpm ÷ (1 − 0) = 129,600 gal. 185,100 gal uses F = 1, and 2,160 gal uses hours instead of minutes.","eq":"10.13","calc":"eq-10.13-10.14","fig":null,"table":null},
  {"id":"10-118","ch":10,"sec":"10.7","page":202,"type":"calc","level":3,"q":"Example 10.6 sized a continuous recovery pump at 214 gpm. If the grower instead builds an intermittent system with a reservoir that stores runoff from two sets, what pump capacity does the book's rule suggest?","opts":["About 107 gpm","About 642 gpm","About 428 gpm","About 214 gpm"],"a":2,"why":"The intermittent pump capacity is usually in direct proportion to reservoir volume. Storing two sets means about twice the continuous pump capacity, 2 × 214 = 428 gpm.","eq":"10.14","calc":"eq-10.13-10.14","fig":null,"table":null},
  {"id":"10-119","ch":10,"sec":"10.7","page":202,"type":"concept","level":3,"q":"Why is the design factor F = 1 (runoff returned to the field of origin) the larger design compared with F = 0?","opts":["F = 1 systems lose more water to seepage","Recycled water adds to the field inflow and itself produces more runoff, so the 1 − R_r denominator enlarges the volume","F = 1 systems must also store rainfall runoff","F = 1 systems run longer sets"],"a":1,"why":"When runoff goes back on the same field, total inflow is Q_w plus the returned flow, and that larger inflow generates more runoff. Dividing by 1 − R_r F accounts for this.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-120","ch":10,"sec":"10.7","page":202,"type":"scenario","level":2,"q":"A grower returns tailwater to the same field by teeing it into his well discharge line. What safety item must he install?","opts":["A flow meter on the tailwater line","A pressure relief valve on the tailwater pump","A screen on the gated pipe outlets","A check valve on the supply pump to prevent contaminated water from flowing back into the aquifer"],"a":3,"why":"If runoff returns to the field of origin and the supply is groundwater, a check valve on the supply pump prevents backflow of contaminated water into the aquifer if the pump fails.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-121","ch":10,"sec":"10.7","page":202,"type":"scenario","level":2,"q":"A grower's tailwater pit fills with mud after every thunderstorm. What does the book recommend?","opts":["Line the pit with concrete","Enlarge the pit to hold storm runoff too","Divert rainfall runoff away from the reservoir, using a gate on the inlet","Run the recovery pump harder during storms"],"a":2,"why":"Rainfall runoff should be kept out of the reservoir to minimize sediment buildup, and a gate on the inlet can block unwanted inflow.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-122","ch":10,"sec":"10.7","page":201,"type":"scenario","level":3,"q":"A grower plans to irrigate a second field using only the tailwater from his first field. What should you warn him about?","opts":["Using tailwater on another field always lowers efficiency below 40%","Tailwater can only be returned to the field it came from","The second field must be upslope of the first","He needs a very accurate estimate of runoff volume, and pesticides from the first field may carry over"],"a":3,"why":"If runoff is the only supply for the receiving field, the book says its volume must be estimated very accurately, and unwanted pesticides can accumulate in runoff from the field of origin.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-123","ch":10,"sec":"10.7","page":201,"type":"scenario","level":1,"q":"A grower's county now limits pumping and forbids irrigation runoff from leaving the farm. Which practice helps him comply?","opts":["Higher furrow stream sizes","A runoff recovery system","Longer furrows","More furrows per set"],"a":1,"why":"Runoff recovery keeps tailwater on the farm and stretches a limited pumped volume, which the book lists as an important advantage where regulations limit pumping or runoff.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-124","ch":10,"sec":"10.8","page":203,"type":"recall","level":1,"q":"What is surge irrigation?","opts":["Applying a large stream briefly to wet the whole field at once","Applying water intermittently, cycling it on and off, instead of continuously for the whole set time","Pumping tailwater back in pulses","Raising the gated pipe pressure in steps"],"a":1,"why":"Surge flow applies water intermittently. It was first studied to reduce runoff, and researchers found it also reduced the time to advance to the end of the field.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-125","ch":10,"sec":"10.8","page":203,"type":"concept","level":2,"q":"Why does surge flow speed advance down the furrow?","opts":["During off time the wetted soil surface consolidates and seals, so rewetted reaches infiltrate less and more water moves on","Surge valves increase total flow from the well","Each surge pushes water faster because of higher pressure","Off time lets the soil crack, raising infiltration"],"a":0,"why":"Brief drying consolidates the surface into a seal. When water returns, intake in the already wetted reach is low, so more water continues down the furrow.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-126","ch":10,"sec":"10.8","page":203,"type":"recall","level":1,"q":"How many cycles and what on times are typical for surge irrigation?","opts":["1 to 2 cycles, with on times of 6 to 12 hours","3 to 6 cycles, with on times of 6 to 12 hours","3 to 6 cycles, with on times of 20 minutes to 2 hours","10 to 20 cycles, with on times of 1 to 5 minutes"],"a":2,"why":"Automatic surge cycling uses 3 to 6 cycles of short duration, 20 minutes to 2 hours, unlike the old practice of returning in 1 or 2 days to finish a set.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-127","ch":10,"sec":"10.8","page":203,"type":"concept","level":2,"q":"On which soils does surge flow usually give the most benefit?","opts":["Any soil on a steep slope with rapid advance","Fine textured soils with low infiltration","Coarse textured soils with high initial infiltration","Compacted soils with low intake"],"a":2,"why":"Fine soils respond less than coarse soils. Steep slopes with rapid advance reduce the effect, and low intake soils (from texture or compaction) see little advance reduction.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-128","ch":10,"sec":"10.8","page":204,"type":"recall","level":2,"q":"How many surge cycles during advance does the book suggest for a long field with high intake soil?","opts":["5 to 6 cycles","8 to 10 cycles","3 to 4 cycles","1 to 2 cycles"],"a":0,"why":"Long fields and high intake soils need more cycles (5 to 6), while short fields with low intake soils need fewer (3 to 4).","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-129","ch":10,"sec":"10.8","page":203,"type":"figure","level":1,"q":"As shown in Figure 10.20, how is a surge valve normally used in the field?","opts":["It splits flow between the head ditch and the tailwater pit","It feeds every furrow in the field at once","It turns the well on and off","It alternates the flow between a left and a right irrigation set"],"a":3,"why":"Rather than turning the water on and off, the valve switches the flow back and forth between two sets, so each side gets equal on and off time.","eq":null,"calc":null,"fig":"10.20","table":null},
  {"id":"10-130","ch":10,"sec":"10.8","page":204,"type":"table","level":1,"q":"From Table 10.7, for six surge cycles during advance, what fraction of the field should water reach in cycle 4, and what is the on time factor?","opts":["0.68 of the field, factor 2.9","0.51 of the field, factor 2.4","1.00 of the field, factor 2.9","0.68 of the field, factor 3.3"],"a":0,"why":"Six cycle values for cycle 4 are fraction 0.68 and factor 2.9. In the four cycle column, cycle 4 is the whole field (1.00).","eq":null,"calc":null,"fig":null,"table":"10.7"},
  {"id":"10-131","ch":10,"sec":"10.8","page":204,"type":"table","level":2,"q":"With four advance cycles, water reaches one fourth of the field in 25 minutes. Using Table 10.7, what is the cycle 3 on time?","opts":["72.5 minutes","60 minutes","75 minutes","47.5 minutes"],"a":1,"why":"Cycle 1 on time is 25 minutes, and cycle 3 uses factor 2.4: 2.4 × 25 = 60 minutes. 75 minutes multiplies by 3 (the cycle number), 47.5 is cycle 2 and 72.5 is cycle 4.","eq":null,"calc":"tab-10.7","fig":null,"table":"10.7"},
  {"id":"10-132","ch":10,"sec":"10.8","page":205,"type":"calc","level":2,"q":"For the same four cycle schedule (cycle 1 on time 25 minutes), how much total clock time does the advance phase take, counting both sides of the valve?","opts":["205 minutes","250 minutes","820 minutes","410 minutes"],"a":3,"why":"On times are 25, 47.5, 60 and 72.5 minutes, totaling 205 minutes per side. Each cycle includes equal off time while the other side runs, so clock time is 2 × 205 = 410 minutes.","eq":null,"calc":"tab-10.7","fig":null,"table":"10.7"},
  {"id":"10-133","ch":10,"sec":"10.8","page":205,"type":"calc","level":3,"q":"The irrigator returns every 12 hours, so each side of the valve gets 360 minutes of on time. Advance used 205 minutes per side, and he wants 4 cutback cycles. What is each cutback on time, and is its factor within Table 10.7?","opts":["About 39 minutes, factor 1.55, within the 0.8 to 1.6 range","About 52 minutes, factor 2.1, above the range","About 90 minutes, factor 3.6, above the range","About 19 minutes, factor 0.78, below the range"],"a":0,"why":"Remaining on time = 360 − 205 = 155 minutes, and 155 ÷ 4 = 38.75 minutes. 38.75 ÷ 25 = 1.55, inside the four cycle post-advance range of 0.8 to 1.6.","eq":null,"calc":"tab-10.7","fig":null,"table":"10.7"},
  {"id":"10-134","ch":10,"sec":"10.8","page":205,"type":"calc","level":3,"q":"A field gets 800 gpm on 30 in rows, every other furrow, 1,200 ft long. Continuous flow waters 45 furrows for 12 hours. Surge flow waters 30 furrows per side for 6 hours of on time. What gross depth does each apply per irrigation?","opts":["Continuous 3.4 in, surge 5.1 in","Continuous 3.4 in, surge 2.6 in","Continuous 2.6 in, surge 3.4 in","Continuous 6.8 in, surge 5.1 in"],"a":1,"why":"W = 60 in. Continuous: 1155 × 800 × 12 ÷ (45 × 60 × 1,200) = 3.42 in. Surge: 1155 × 800 × 6 ÷ (30 × 60 × 1,200) = 2.57 in. Using W = 30 in doubles both.","eq":"10.4","calc":"eq-10.4","fig":null,"table":null},
  {"id":"10-135","ch":10,"sec":"10.8","page":205,"type":"calc","level":3,"q":"Surge irrigation applies 2.57 in gross with an average infiltrated depth of 2.0 in and DU = 0.80. SWD at irrigation is 1.5 in (0.25 in/day for 6 days). What is E_LQ?","opts":["78%","44%","58%","62%"],"a":2,"why":"d_LQ = 0.80 × 2.0 = 1.6 in, more than SWD, so d_e = 1.5 in. E_LQ = 1.5 ÷ 2.57 = 58%. 62% uses d_LQ, and 44% is the continuous flow result (1.5 ÷ 3.42).","eq":"5.11","calc":"eq-5.9-5.11","fig":null,"table":null},
  {"id":"10-136","ch":10,"sec":"10.8","page":205,"type":"calc","level":3,"q":"A field needs 10 in of effective irrigation a year, with 1.5 in effective per irrigation. Continuous flow applies 3.42 in gross per irrigation and surge applies 2.57 in. How much water does surging save per year?","opts":["About 5.7 in/yr, a 25% saving","About 0.85 in/yr, a 25% saving","About 8.5 in/yr, a 33% saving","About 5.7 in/yr, a 33% saving"],"a":0,"why":"Irrigations per year = 10 ÷ 1.5 = 6.7. Annual gross: 6.7 × 3.42 = 22.8 in and 6.7 × 2.57 = 17.1 in, saving 5.7 in/yr. 5.7 ÷ 22.8 = 25%. 33% divides by the surge total instead.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-137","ch":10,"sec":"10.8","page":204,"type":"scenario","level":2,"q":"A grower using surge says, \"Water still is not reaching the end after the last advance cycle.\" What are his options?","opts":["Switch the valve to cutback right away","Increase the number of surge cycles or water fewer furrows per set to raise the stream size","Water more furrows per set","Decrease the number of surge cycles"],"a":1,"why":"If water does not reach the end by the last cycle, the book says increase cycles or decrease furrows per set. More furrows or fewer cycles are the fixes for reaching the end too soon.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-138","ch":10,"sec":"10.8","page":204,"type":"scenario","level":2,"q":"A surge irrigator says, \"Water is reaching the end of the field well before the last advance cycle.\" What should he change?","opts":["Add more surge cycles","Lengthen the cycle 1 on time","Water fewer furrows per set","Water more furrows per set or use fewer surge cycles"],"a":3,"why":"Early arrival means the stream is too large or there are too many cycles. Increasing furrows (smaller stream) or decreasing cycles brings the advance back in line.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-139","ch":10,"sec":"10.8","page":204,"type":"scenario","level":3,"q":"A grower tried surge on his silty clay loam and says, \"Advance time hardly changed. Was the valve a waste?\" What do you tell him?","opts":["Low intake soils respond little to surge, but the valve still gives semi-automation, labor savings and less runoff with cutback cycling","Yes, surge only works on clay soils","He set it up wrong, since surge always halves advance time","He should switch to continuous flow with blocked ends"],"a":0,"why":"Fine, low intake soils respond less to surge. The book notes that even without faster advance there can be labor savings and runoff reduction, and two-set automatic operation.","eq":null,"calc":null,"fig":null,"table":null},
  {"id":"10-140","ch":10,"sec":"10.8","page":204,"type":"scenario","level":2,"q":"A grower setting up a surge valve on a 1,200 ft field with four advance cycles asks how to set the cycle 1 on time. What do you tell him?","opts":["Time how long water takes to reach the end and divide by four","Time how long water takes to reach 300 ft (one fourth of the field) and use that as cycle 1 on time","Use 2 hours for cycle 1 on every field","Divide the set time by the number of cycles"],"a":1,"why":"Each advance cycle moves water about 1/n of the field. Cycle 1 on time is the time to reach the first quarter, and later cycles multiply it by the Table 10.7 factors.","eq":null,"calc":null,"fig":null,"table":null}
]);
